  public static final PhonAdapter<TerminalConnectResult> ADAPTER = new PhonAdapter<>() {
    @Override public SchemaClosure schema() { return SCHEMA_CLOSURE; }
    @Override public void encode(PhonEncoder encoder, TerminalConnectResult value) throws PhonException {
      encoder.writeString(value.sessionId());
      encoder.writeAdapted(TerminalCapabilities.ADAPTER, value.capabilities());
      encoder.writeAdapted(TerminalSurfaceMetrics.ADAPTER, value.surface());
      encoder.writeI64(value.serverSequence());
      encoder.writeAdapted(TerminalState.ADAPTER, value.state());
      encoder.writeString(value.correlationId());
      encoder.writeBool(value.tuningPresent());
      encoder.writeAdapted(TerminalTuningMetrics.ADAPTER, value.tuning());
    }
    @Override public TerminalConnectResult decode(PhonDecoder decoder) throws PhonException { return new TerminalConnectResult(decoder.readString(), decoder.readAdapted(TerminalCapabilities.ADAPTER), decoder.readAdapted(TerminalSurfaceMetrics.ADAPTER), decoder.readI64(), decoder.readAdapted(TerminalState.ADAPTER), decoder.readString(), decoder.readBool(), decoder.readAdapted(TerminalTuningMetrics.ADAPTER)); }
  };

  @Override public boolean equals(Object other) {
    if (!(other instanceof TerminalConnectResult that)) return false;
    return Objects.deepEquals(sessionId, that.sessionId) && Objects.deepEquals(capabilities, that.capabilities) && Objects.deepEquals(surface, that.surface) && Objects.deepEquals(serverSequence, that.serverSequence) && Objects.deepEquals(state, that.state) && Objects.deepEquals(correlationId, that.correlationId) && Objects.deepEquals(tuningPresent, that.tuningPresent) && Objects.deepEquals(tuning, that.tuning);
  }
  @Override public int hashCode() { return Objects.hash(sessionId, capabilities, surface, serverSequence, state, correlationId, tuningPresent, tuning); }
  @Override public String toString() { return "TerminalConnectResult" + java.util.List.of(sessionId, capabilities, surface, serverSequence, state, correlationId, tuningPresent, tuning); }
